export function certificateLine(boat: string, cert: Certificate | null, today: number): string {
  const base = certificateLineBase(boat, cert, today);
  if (cert === null || today < cert.from) return base;
  // Assumes `expires` is the first day the certificate no longer covers.
  const left = cert.expires - today;
  if (left <= 0) return `${base}, lapsed`;
  return `${base}, ${left} ${left === 1 ? "day" : "days"} left`;
}

